import{_ as p,a0 as u,w as o,s as r,I as a,x as i,a1 as s,A as n,ao as l}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const w=JSON.parse('{"title":"安装 Ubuntu 22.10 后要做的 10 件事 | LCTT x X-CMD","titleTemplate":false,"description":"安装 Ubuntu 22.10 后要做的 10 件事 | LCTT (202210) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安装 Ubuntu 22.10 后要做的 10 件事 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安装 Ubuntu 22.10 后要做的 10 件事 | LCTT (202210) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202210/20221021.2 ⭐️⭐️  10 Things to Do After Installing Ubuntu 22.10 [With Bonus Tip]","title":"安装 Ubuntu 22.10 后要做的 10 件事","tag":"202210","desc":""},"relativePath":"202210/20221021.2 ⭐️⭐️  10 Things to Do After Installing Ubuntu 22.10 [With Bonus Tip].md","filePath":"[post].md"}'),d={name:"202210/20221021.2 ⭐️⭐️  10 Things to Do After Installing Ubuntu 22.10 [With Bonus Tip].md"};function b(h,t,g,f,k,m){const e=u("Link");return o(),r("div",null,[t[32]||(t[32]=a("h1",{id:"安装-ubuntu-22-10-后要做的-10-件事",tabindex:"-1"},[i("安装 Ubuntu 22.10 后要做的 10 件事 "),a("a",{class:"header-anchor",href:"#安装-ubuntu-22-10-后要做的-10-件事","aria-label":"Permalink to “安装 Ubuntu 22.10 后要做的 10 件事”"},"​")],-1)),t[33]||(t[33]=a("blockquote",null,[a("p",null,"以下是我们安装 Ubuntu 22.10 “Kinetic Kudu”（GNOME 版）后，推荐做的 10 件事列表。")],-1)),t[34]||(t[34]=a("p",null,[a("img",{src:"https://www.debugpoint.com/wp-content/uploads/2022/10/u2210-things-hd-1024x576.jpg",alt:""})],-1)),a("p",null,[t[1]||(t[1]=i("Ubuntu 22.10 带来了很多令人兴奋的新功能，例如 GNOME 43、最新的内核、重新设计的托盘菜单、文件应用的功能和 Pipewire 等 ",-1)),s(e,{href:"https://www.debugpoint.com/ubuntu-22-10/"},{default:n(()=>[...t[0]||(t[0]=[i("新功能",-1)])]),_:1}),t[2]||(t[2]=i("。",-1))]),t[35]||(t[35]=l('<p>我相信你已经迫不及待地想尝试 Ubuntu 22.10 上的这些新功能了。</p><p>但是请先等一等。</p><p>在你前往享受你新安装的 Ubuntu 22.10 之前，我要向你推荐一个不容错过的 Ubuntu 定制技巧列表。</p><h3 id="安装-ubuntu-22-10-后要做的-10-件事-1" tabindex="-1">安装 Ubuntu 22.10 后要做的 10 件事 <a class="header-anchor" href="#安装-ubuntu-22-10-后要做的-10-件事-1" aria-label="Permalink to “安装 Ubuntu 22.10 后要做的 10 件事”">​</a></h3><h4 id="_1、更新你的系统" tabindex="-1">1、更新你的系统 <a class="header-anchor" href="#_1、更新你的系统" aria-label="Permalink to “1、更新你的系统”">​</a></h4><p>安装好 Ubuntu 22.10 后，第一件要做的事就是更新你的系统。因为时差的原因，最新的 ISO 镜像通常不会包括所有的系统更新。所以，你要打开一个终端窗口，并运行以下命令，来更新你的系统。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt update &amp;&amp; sudo apt upgrade</span></span></code></pre></div><p>上述命令执行完成后，你就可以进行下一步啦。</p><h4 id="_2、删除-firefox-snap-并安装-flatpak-或者-deb-版本的-firefox" tabindex="-1">2、删除 Firefox Snap，并安装 Flatpak 或者 deb 版本的 Firefox <a class="header-anchor" href="#_2、删除-firefox-snap-并安装-flatpak-或者-deb-版本的-firefox" aria-label="Permalink to “2、删除 Firefox Snap，并安装 Flatpak 或者 deb 版本的 Firefox”">​</a></h4><p>自去年发布的 Ubuntu 21.10 版本以来，默认的网页浏览器 Firefox 开始以 Snap 软件包的形式出现。如果你是普通用户，这可能不是一个问题或者需要担心的事情。但是出于几个原因，例如 Snap 软件包的 Firefox 启动时间较长、且当 Firefox 有后台更新时，会有不必要的 Snap 更新通知等等原因，导致许多用户不太喜欢 Firefox 的 Snap 软件包。</p>',10)),a("p",null,[t[5]||(t[5]=i("因此，你可以按照 ",-1)),s(e,{href:"https://www.debugpoint.com/remove-firefox-snap-ubuntu/"},{default:n(()=>[...t[3]||(t[3]=[i("我写的另一篇操作指南",-1)])]),_:1}),t[6]||(t[6]=i("，来完全删除 Firefox 的 Snap 软件包。这一过程有点复杂，需要花费一点时间。删除完成后，再从个人软件包存档（PPA）安装 deb 版本的 Firefox，或者使用 ",-1)),s(e,{href:"https://flathub.org/apps/details/org.mozilla.firefox"},{default:n(()=>[...t[4]||(t[4]=[i("Flatpak 版本",-1)])]),_:1}),t[7]||(t[7]=i(" 的 Firefox。",-1))]),t[36]||(t[36]=l('<p>这是一个可选的动作，你也可以跳过这一步骤。</p><h4 id="_3、安装并启用-flatpak" tabindex="-1">3、安装并启用 Flatpak <a class="header-anchor" href="#_3、安装并启用-flatpak" aria-label="Permalink to “3、安装并启用 Flatpak”">​</a></h4><p>虽然，几乎所有最新的 Linux 发行版都会默认安装 Flatpak，但是 Ubuntu 并没有默认安装 Flatpak，这是因为 Ubuntu 使用了它自己的沙箱技术 Snap。</p><p>但 Flatpak 这一应用程序还是最适合于每个人。Flatpak 能够帮助你快速安装多个应用程序，并在使用过程中无需担心依赖性和其他事情。</p><p>大多数 Flatpak 应用程序都在集中的仓库 Flathub 中。</p><p>要在 Ubuntu 22.10 中启用 Flatpak 应用程序，请按照以下命令进行操作。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install flatpakflatpak remote-add --if-not-exists flathub https://flathub.org/repo/flathub.flatpakreporeboot</span></span></code></pre></div>',7)),a("p",null,[t[9]||(t[9]=i("如果你想进一步了解关于此安装过程的更多信息，请阅读我们不久前发布的 ",-1)),s(e,{href:"https://www.debugpoint.com/how-to-install-flatpak-apps-ubuntu-linux/"},{default:n(()=>[...t[8]||(t[8]=[i("指南",-1)])]),_:1}),t[10]||(t[10]=i("。",-1))]),t[37]||(t[37]=l('<h4 id="_4、查看隐私设置" tabindex="-1">4、查看隐私设置 <a class="header-anchor" href="#_4、查看隐私设置" aria-label="Permalink to “4、查看隐私设置”">​</a></h4><p>我建议你在安装 Ubuntu 后，手动退出任何数据收集项。大家都知道，无论怎么努力尝试，在互联网上保护自己的隐私都很困难。因此，这些小步骤很重要。</p><p>要配置隐私项，请打开“<ruby>设置<rt>Settings</rt></ruby>”并选择“<ruby>隐私<rt>Privacy</rt></ruby>”。然后查看隐私菜单下列出的项目。</p><p>此外，请确保禁用对 Ubuntu 服务器的后台报告。需要运行以下命令来手动禁用，因为在设置中没有禁用它的选项。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ubuntu-report -f send no</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/10/Turn-off-location-services-in-Ubuntu-22.10.jpg" alt="Turn off location services in Ubuntu 22.10"></p><h4 id="_5、探索-gnome-43-的功能" tabindex="-1">5、探索 GNOME 43 的功能 <a class="header-anchor" href="#_5、探索-gnome-43-的功能" aria-label="Permalink to “5、探索 GNOME 43 的功能”">​</a></h4><p>在 Ubuntu 22.10 版本中，最具视觉和功能性的变化是 GNOME 43。因为 GNOME 43 有一些根本性和核心变化，所以它会影响每个人和他们的工作。GNOME 43 带来了一个新的药丸形状的托盘菜单，并更新了文件应用和 GNOME Web 等原生应用程序的功能。</p>',8)),a("p",null,[t[12]||(t[12]=i("请查看更为详细的 ",-1)),s(e,{href:"https://www.debugpoint.com/gnome-43/"},{default:n(()=>[...t[11]||(t[11]=[i("GNOME 43 功能",-1)])]),_:1}),t[13]||(t[13]=i(" 一文，以了解更多信息，或者你也可以自己探索 GNOME 43。",-1))]),t[38]||(t[38]=l('<p><img src="https://www.debugpoint.com/wp-content/uploads/2022/08/Quick-Settings-Demo-in-GNOME-43.gif" alt="Quick Settings Demo in GNOME 43"></p><h4 id="_6、确保音频可以与-pipewire-配合使用" tabindex="-1">6、确保音频可以与 Pipewire 配合使用 <a class="header-anchor" href="#_6、确保音频可以与-pipewire-配合使用" aria-label="Permalink to “6、确保音频可以与 Pipewire 配合使用”">​</a></h4><p>如果你经常使用音频，或者你的工作范围涉及到声音捕获、播放等内容，请确保在 Ubuntu 22.10 中，你的音频在有线或蓝牙情况下都能正常工作。</p><p>因为 Ubuntu 22.10 这个版本中的音频服务器是多年来第一次发生了变化，传统的 PulseAudio 被现代的 Pipewire 所取代。因此，请务必进行验证音频是否能正常使用。</p><h4 id="_7、安装其他软件包" tabindex="-1">7、安装其他软件包 <a class="header-anchor" href="#_7、安装其他软件包" aria-label="Permalink to “7、安装其他软件包”">​</a></h4><p>确保你可以在 Ubuntu 桌面上播放所有视频和音频格式是很重要的。如果你在设置期间跳过了额外的软件包安装，可以通过以下命令进行安装。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install ubuntu-restricted-extras</span></span></code></pre></div><p>这可以解决 Ubuntu 中的任何视频或音频的播放问题，特别是 GNOME 视频无法播放的情况（因为GNOME 视频在默认情况下将无法播放任何内容）。</p><h4 id="_8、安装基本的应用程序" tabindex="-1">8、安装基本的应用程序 <a class="header-anchor" href="#_8、安装基本的应用程序" aria-label="Permalink to “8、安装基本的应用程序”">​</a></h4><p>带有 GNOME 的 Ubuntu 基础版本只有非常基本的应用程序。因此，在你使用 Ubuntu 之前，你需要安装一些其他必要的应用程序。</p><p>由于每个人的工作范围不同，每个人所需的应用程序也都不同。因此，在这里我仅提供一个通用的应用程序的列表，我认为你可以把这些应用程序都安装上，因为这些应用程序对所有人来说都很常用。</p><ul><li>GIMP – 进阶的照片编辑器</li><li>VLC – 无需额外编解码器即可播放任何内容的媒体播放器</li><li>Leafpad – 轻量级文本编辑器（甚至比默认的文本编辑器 gedit 还要更轻量级）</li><li>Synaptic – 更好的软件包管理器</li></ul><p>安装这些应用程序的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install -y gimp vlc leafpad synaptic</span></span></code></pre></div><h4 id="_9、获取一些-gnome-扩展" tabindex="-1">9、获取一些 GNOME 扩展 <a class="header-anchor" href="#_9、获取一些-gnome-扩展" aria-label="Permalink to “9、获取一些 GNOME 扩展”">​</a></h4><p>你可以使用几个很酷的扩展程序，来扩展 GNOME 43 的功能，包括自定义顶部栏、托盘、更改 adwaita 外观等等。首先，使用下面的命令通过 Flatpak 来安装 GNOME 扩展管理器。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub com.mattjakeman.ExtensionManager</span></span></code></pre></div><p>安装完成后，你就可以在 GNOME 扩展管理器中搜索你想要的任何扩展了。以下是一些必要扩展，你可以用它们来快速扩展 GNOME 43 的功能，我认为它们非常适合你全新的 Ubuntu 桌面。你只需在扩展管理器应用程序中，搜索这些名称即可。</p><ul><li>Caffeine</li><li>Custom Hot Corners</li><li>Dash to Dock</li><li>Blur my shell</li><li>Gradients</li><li>Hide Activities Button</li><li>Net speed simplified</li></ul><h4 id="_10、准备备份" tabindex="-1">10、准备备份 <a class="header-anchor" href="#_10、准备备份" aria-label="Permalink to “10、准备备份”">​</a></h4><p>我们总是在我们遇到困难时，才觉得有必要备份。所以，请确保从一开始你就为备份做好了准备。理想的备份应用程序是 Timeshift，它很容易安装和使用。</p><p>以下是你可以从终端安装 Timeshift 的一组命令。安装完成后，你可以打开 Timeshift，并按照屏幕上的说明，设置备份了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository -y ppa:teejee2008/ppasudo apt-get updatesudo apt-get install timeshift</span></span></code></pre></div><h3 id="额外小技巧" tabindex="-1">额外小技巧 <a class="header-anchor" href="#额外小技巧" aria-label="Permalink to “额外小技巧”">​</a></h3><p>如果你想进一步定制你新安装的 Ubuntu 系统，以下是一些额外的小技巧。</p><h4 id="安装漂亮的字体" tabindex="-1">安装漂亮的字体 <a class="header-anchor" href="#安装漂亮的字体" aria-label="Permalink to “安装漂亮的字体”">​</a></h4><p>字体是一个很小却影响很大的设置项。虽然，Ubuntu 自带有好用的“Ubuntu regular”字体。</p><p>但是，你也可以从 Ubuntu 的官方仓库中安装一些其他漂亮的字体。以下是安装字体的一些命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install fonts-roboto fonts-cascadia-code fonts-firacode</span></span></code></pre></div>',29)),a("p",null,[t[15]||(t[15]=i("安装完成后，你可以使用 ",-1)),s(e,{href:"https://www.debugpoint.com/customize-your-ubuntu-desktop-using-gnome-tweak/"},{default:n(()=>[...t[14]||(t[14]=[i("GNOME Tweak 工具",-1)])]),_:1}),t[16]||(t[16]=i("，来更改字体。",-1))]),t[39]||(t[39]=l('<h4 id="安装-tlp" tabindex="-1">安装 TLP <a class="header-anchor" href="#安装-tlp" aria-label="Permalink to “安装 TLP”">​</a></h4><p>如果你经常使用笔记本电脑，那么你要好好爱惜电脑的电池。虽然电池用久了总是会损坏的，但你可以采取一些步骤，来减缓电池的老化。TLP 是 Linux 中自动优化电池使用、减缓电池老化的最好的程序之一。你可以使用以下命令来安装 TLP。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install tlp</span></span></code></pre></div><p>我建议你将电池的电量始终保持在 50% 至 80% 之间。不要过度充电或让电池电量消耗到 50% 以下，也不要给电脑连续插电。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>以上就是安装桌面 Ubuntu 22.10 后要做的 10 件事啦。</p><p>我希望这篇文章会对你有帮助，你能够通过本文的方法来定制和调整你的 Ubuntu 桌面。那么你认为在安装好 Ubuntu 后，什么事是最推荐做的呢？请在评论区中告诉我吧。</p><hr>',8)),a("p",null,[t[18]||(t[18]=i("via: ",-1)),s(e,{href:"https://www.debugpoint.com/things-to-do-ubuntu-22-10/"},{default:n(()=>[...t[17]||(t[17]=[i("https://www.debugpoint.com/things-to-do-ubuntu-22-10/",-1)])]),_:1})]),a("p",null,[t[23]||(t[23]=i("作者：",-1)),s(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:n(()=>[...t[19]||(t[19]=[i("Arindam",-1)])]),_:1}),t[24]||(t[24]=i(" 选题：",-1)),s(e,{href:"https://github.com/lkxed"},{default:n(()=>[...t[20]||(t[20]=[i("lkxed",-1)])]),_:1}),t[25]||(t[25]=i(" 译者：",-1)),s(e,{href:"https://github.com/chai001125"},{default:n(()=>[...t[21]||(t[21]=[i("chai001125",-1)])]),_:1}),t[26]||(t[26]=i(" 校对：",-1)),s(e,{href:"https://github.com/%E6%A0%A1%E5%AF%B9%E8%80%85ID"},{default:n(()=>[...t[22]||(t[22]=[i("校对者ID",-1)])]),_:1})]),a("p",null,[t[29]||(t[29]=i("本文由 ",-1)),s(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[27]||(t[27]=[i("LCTT",-1)])]),_:1}),t[30]||(t[30]=i(" 原创编译，",-1)),s(e,{href:"https://linux.cn/"},{default:n(()=>[...t[28]||(t[28]=[i("Linux中国",-1)])]),_:1}),t[31]||(t[31]=i(" 荣誉推出",-1))])])}const _=p(d,[["render",b]]);export{w as __pageData,_ as default};
